package ru.evolenta.pgs.worker;
import java.util.*;import static ru.evolenta.pgs.worker.Util.*;
public final class Context {
    public final Command command;public final PgsApi api;public Map<String,Object> appeal,sub,xsd;
    private Operations.Lease lease=()->{};
    public void setLease(Operations.Lease lease){this.lease=lease;}
    public byte[] download(String fileId,long maxBytes)throws Exception{lease.check();byte[] bytes=api.download(command.collection,command.mainId,fileId,maxBytes);lease.check();return bytes;}
    public Context(Command command,PgsApi api)throws Exception{this.command=command;this.api=api;reload();}
    public void reload()throws Exception{appeal=api.find(command.collection,command.mainId);if(!command.mainId.equals(id(appeal)))throw new IllegalStateException("Дело не найдено");List<Map<String,Object>> found=new ArrayList<Map<String,Object>>();for(Map<String,Object>s:maps(appeal.get("subservices"))){Map<String,Object> info=map(s.get("camundaProcessInfo"));if(command.processId.equals(clean(first(info.get("id"),info.get("instanceId"))))&&command.businessInfoId.equals(clean(info.get("camundaBusinessInfoId"))))found.add(s);}if(found.size()!=1)throw new IllegalStateException("Не найдена однозначная подуслуга текущего процесса");sub=found.get(0);xsd=copy(map(sub.get("xsdData")));if(!present(sub.get("guid")))throw new IllegalStateException("Нет guid подуслуги");}
    public void saveAppeal(Map<String,Object> patch)throws Exception{lease.check();api.update(command.collection,command.mainId,clean(appeal.get("guid")),patch);appeal.putAll(patch);}
    public void saveSub(Map<String,Object> patch)throws Exception{lease.check();api.updateSub(command.collection,command.mainId,clean(sub.get("guid")),clean(first(sub.get("parentEntries"),command.collection+".subservices")),patch);sub.putAll(patch);if(patch.containsKey("xsdData"))xsd=copy(map(patch.get("xsdData")));}
    public void saveResult(Map<String,Object> draft,Map<String,Object> result)throws Exception{Map<String,Object> fresh=api.find(command.collection,command.mainId);Map<String,Object> current=null;for(Map<String,Object>s:maps(fresh.get("subservices")))if(clean(sub.get("guid")).equals(clean(s.get("guid"))))current=s;if(current==null)throw new IllegalStateException("Подуслуга исчезла");Map<String,Object>x=copy(map(current.get("xsdData")));x.putAll(result);x.put("rbuImportResult",result);x.put("rbuImportDraft",draft);saveSub(obj("xsdData",x,"rbuImportResult",result,"rbuImportDraft",draft));}
    public Map<String,Object> selection(String name){Map<String,Object> result=new LinkedHashMap<String,Object>();Object[] candidates={at(xsd,"mainElement."+name),at(sub,"mainElement.xsdData."+name),xsd.get(name),appeal.get(name)};for(Object o:candidates)if(o instanceof Map)result.putAll(map(o));return result;}
    public static Map<String,Object> filter(String field,Object value){return obj("field",field,"operator","eq","value",value);}
    public List<Map<String,Object>> searchAll(String c,List<Object> filters)throws Exception{List<Map<String,Object>> all=new ArrayList<Map<String,Object>>();Set<String> ids=new HashSet<String>();for(int p=0;p<1000;p++){List<Map<String,Object>> batch=api.search(c,filters,p,100);if(batch.isEmpty())return all;int added=0;for(Map<String,Object> r:batch){String id=id(r);if(id.isEmpty())throw new IllegalStateException("Record has no ID");if(ids.add(id)){all.add(r);added++;}}if(added==0)throw new IllegalStateException("API ignored pagination");if(all.size()>20000)throw new IllegalStateException("Search memory limit exceeded; narrow filters");}throw new IllegalStateException("Pagination limit exceeded");}
}
